    /* ---- src/lib/districts.js ---- */
    /**
     * 区县级行政区搜索（内置索引，不联网）。
     *
     * 为什么内置：Open-Meteo 的地理编码用的是 GeoNames 的「城市」子集，实测
     * 「徐汇区 / 浦东新区 / 静安区 / 岱山县」全部返回 0 条，而 Nominatim 在本机
     * 和大陆网络下都连不上。要让手动搜索真正落到区县，只能自带一份索引。
     *
     * 数据：GeoNames（CC BY 4.0）中国 ADM1/ADM2/ADM3 行政单元，构建期生成
     * `districts-data.js`（约 100 KiB，2895 个区县 + 360 个地级市 + 31 个省级），
     * 坐标为行政中心点、保留两位小数（约 1 km），对「选城市」这个用途足够。
     */


    const CJK = /[\u4e00-\u9fff]/;
    const SUFFIXES = /(特别行政区|自治区|自治州|自治县|新区|地区|省|市|区|县|旗|盟|州)$/;
    const DISTRICT_SUFFIX = /[区县旗]$/;

    /**
     * 更名 / 俗名 → 现行区县名。
     *
     * GeoNames 是一份快照，个别行政区后来改名或被撤并（例如两江新区成立后新区名不在
     * 索引里），这里补几条常用别名。
     */
    const DISTRICT_ALIASES = {
      西海岸新区: '黄岛区',
      青岛西海岸新区: '黄岛区',
      胶南: '黄岛区',
      胶南市: '黄岛区',
      两江新区: '渝北区'
    };

    function stripSuffix(text) {
      return String(text || '').replace(SUFFIXES, '');
    }

    /** 一次查询的所有写法：原名、去后缀、别名。 */
    function districtVariants(query) {
      const raw = String(query || '').trim();
      if (!raw) return [];
      const out = new Set([raw]);
      const stripped = stripSuffix(raw);
      if (stripped && stripped !== raw) out.add(stripped);
      const alias = DISTRICT_ALIASES[raw];
      if (alias) {
        out.add(alias);
        const aliasStripped = stripSuffix(alias);
        if (aliasStripped) out.add(aliasStripped);
      }
      return Array.from(out);
    }

    function cityName(index) {
      const city = CN_CITIES[index];
      if (!city) return '';
      return city[0];
    }

    function provinceName(index) {
      const province = CN_PROVINCES[index];
      return province ? province[0] : '';
    }

    function provinceOfCity(index) {
      const city = CN_CITIES[index];
      return city && city[1] >= 0 ? provinceName(city[1]) : '';
    }

    /**
     * Score one name against the variants; higher wins, `0` = no match.
     *
     * 精确命中 > 以查询开头 > 包含查询，长度差越小越靠前，这样「徐汇」既能命中
     * 「徐汇区」，也不会让更长的名字抢到前面。
     */
    function scoreName(name, variants) {
      let best = 0;
      for (const variant of variants) {
        if (!variant) continue;
        if (name === variant) best = Math.max(best, 120);
        else if (name.startsWith(variant)) best = Math.max(best, 100 - (name.length - variant.length));
        else if (name.includes(variant)) best = Math.max(best, 60 - name.indexOf(variant));
      }
      return best;
    }

    /**
     * Search the bundled index.
     *
     * @param {string} query 用户输入（只处理中文；英文交给 Open-Meteo）
     * @param {{lang?: string, limit?: number}} [options]
     * @returns {Array<object>} picker 形状的命中项，区县在前、城市在后
     */
    function searchDistricts(query, options) {
      const settings = options || {};
      const lang = settings.lang === 'en' ? 'en' : 'zh';
      const limit = Number.isFinite(settings.limit) ? Math.max(1, Math.floor(settings.limit)) : 6;
      const raw = String(query || '').trim();
      if (!raw || !CJK.test(raw)) return [];
      const variants = districtVariants(raw);
      if (variants.length === 0) return [];

      const hits = [];
      for (let index = 0; index < CN_DISTRICTS.length; index += 1) {
        const [name, lat, lon, cityIndex] = CN_DISTRICTS[index];
        const score = scoreName(name, variants);
        if (score <= 0) continue;
        const city = cityName(cityIndex);
        const province = provinceOfCity(cityIndex);
        hits.push({
          score,
          kind: 'district',
          id: `cn-d-${cityIndex}-${index}`,
          name,
          region: province,
          subtitle: [city, province].filter(Boolean).join(' · '),
          country: lang === 'en' ? 'China' : '中国',
          countryCode: 'CN',
          city: city || provinceOfCity(cityIndex),
          district: name,
          featureCode: 'ADM3',
          source: 'district',
          lat,
          lon
        });
      }

      // 市级命中作为兜底：输入恰好是城市名时也能选中，且比区县略靠后。
      for (let index = 0; index < CN_CITIES.length; index += 1) {
        const [name, provinceIndex, lat, lon] = CN_CITIES[index];
        const score = scoreName(name, variants);
        if (score <= 0) continue;
        hits.push({
          score: score - 10,
          kind: 'city',
          id: `cn-c-${index}`,
          name,
          region: provinceName(provinceIndex),
          subtitle: provinceName(provinceIndex),
          country: lang === 'en' ? 'China' : '中国',
          countryCode: 'CN',
          city: name,
          district: '',
          featureCode: 'ADM2',
          source: 'district',
          lat,
          lon
        });
      }

      hits.sort((left, right) => {
        if (right.score !== left.score) return right.score - left.score;
        if (left.name.length !== right.name.length) return left.name.length - right.name.length;
        return left.name.localeCompare(right.name, 'zh');
      });

      // 同名区县（如朝阳区 ×2）都保留，靠 region 区分；完全相同的名字+坐标才去重。
      const seen = new Set();
      const out = [];
      for (const hit of hits) {
        const key = `${hit.name}|${hit.lat}|${hit.lon}`;
        if (seen.has(key)) continue;
        seen.add(key);
        out.push(hit);
        if (out.length >= limit) break;
      }
      return out;
    }

    /** True when the place name looks like a county/district (for UI tagging). */
    function looksLikeDistrict(name) {
      return DISTRICT_SUFFIX.test(String(name || ''));
    }

    /* ---- src/lib/geo.js ---- */
    /**
     * Network location: public-IP geolocation plus locality naming.
     *
     * Design constraints, learned the hard way:
     * - No single IP-geolocation service is reliable everywhere (rate limits,
     *   carrier NAT, proxies, regional blocking), so several are raced and the
     *   first usable answer wins. One provider failing must never fail the panel.
     * - The result is city-level at best and can be a proxy exit, therefore the
     *   panel always shows the source and offers a manual override.
     * - Nothing here performs I/O itself: the caller injects `fetchJson`, which
     *   keeps every branch unit-testable.
     */


    const GEO_LOOKUP_TIMEOUT_MS = 6000;
    const GEO_REQUEST_TIMEOUT_MS = 5000;
    const REVERSE_GEOCODE_URL = 'https://api.bigdatacloud.net/data/reverse-geocode-client';
    const CITY_SEARCH_URL = 'https://geocoding-api.open-meteo.com/v1/search';

    const GEO_PROVIDERS = [
      {
        id: 'ipwho.is',
        url: 'https://ipwho.is/',
        parse: parseIpWhoIs
      },
      {
        id: 'ipinfo.io',
        url: 'https://ipinfo.io/json',
        parse: parseIpinfo
      },
      {
        id: 'ip.sb',
        url: 'https://api.ip.sb/geoip',
        parse: parseIpSb
      }
    ];

    function toFiniteNumber(value) {
      const numeric = typeof value === 'string' ? Number(value.trim()) : value;
      return typeof numeric === 'number' && Number.isFinite(numeric) ? numeric : null;
    }

    function cleanName(value) {
      if (typeof value !== 'string') return '';
      const text = value.trim();
      return text.length > 0 ? text : '';
    }

    /** Validate and normalize one provider answer; `null` means "unusable". */
    function normalizeGeo(raw) {
      if (!raw || typeof raw !== 'object') return null;
      const lat = toFiniteNumber(raw.lat);
      const lon = toFiniteNumber(raw.lon);
      if (lat === null || lon === null) return null;
      if (lat < -90 || lat > 90 || lon < -180 || lon > 180) return null;
      return {
        lat,
        lon,
        city: cleanName(raw.city),
        region: cleanName(raw.region),
        country: cleanName(raw.country),
        countryCode: cleanName(raw.countryCode).toUpperCase(),
        timezone: cleanName(raw.timezone),
        ip: cleanName(raw.ip),
        provider: cleanName(raw.provider),
        source: 'network'
      };
    }

    /** `https://ipwho.is/` */
    function parseIpWhoIs(json) {
      if (!json || json.success === false) return null;
      return normalizeGeo({
        lat: json.latitude,
        lon: json.longitude,
        city: json.city,
        region: json.region,
        country: json.country,
        countryCode: json.country_code,
        timezone: json.timezone && json.timezone.id ? json.timezone.id : json.timezone,
        ip: json.ip,
        provider: 'ipwho.is'
      });
    }

    /** `https://ipinfo.io/json` — coordinates arrive as `"lat,lon"`. */
    function parseIpinfo(json) {
      if (!json || typeof json !== 'object') return null;
      const loc = typeof json.loc === 'string' ? json.loc.split(',') : [];
      return normalizeGeo({
        lat: loc.length === 2 ? loc[0] : null,
        lon: loc.length === 2 ? loc[1] : null,
        city: json.city,
        region: json.region,
        country: json.country,
        countryCode: json.country,
        timezone: json.timezone,
        ip: json.ip,
        provider: 'ipinfo.io'
      });
    }

    /** `https://api.ip.sb/geoip` */
    function parseIpSb(json) {
      if (!json || typeof json !== 'object' || json.ip === undefined) return null;
      return normalizeGeo({
        lat: json.latitude,
        lon: json.longitude,
        city: json.city,
        region: json.region,
        country: json.country,
        countryCode: json.country_code,
        timezone: json.timezone,
        ip: json.ip,
        provider: 'ip.sb'
      });
    }

    /**
     * Race every IP-geolocation provider and resolve with the first usable answer.
     *
     * @param {(url: string, options: object) => Promise<any>} fetchJson injected JSON fetcher
     * @param {{signal?: AbortSignal, timeoutMs?: number, providers?: Array<any>}} [options]
     * @returns {Promise<object|null>} normalized location, or `null` when nothing usable
     */
    function lookupNetworkLocation(fetchJson, options) {
      const settings = options || {};
      const providers = Array.isArray(settings.providers) ? settings.providers : GEO_PROVIDERS;
      const timeoutMs = Number.isFinite(settings.timeoutMs) ? settings.timeoutMs : GEO_LOOKUP_TIMEOUT_MS;
      const externalSignal = settings.signal;
      if (providers.length === 0) return Promise.resolve(null);

      return new Promise(resolve => {
        const controller = new AbortController();
        let settled = false;
        let pending = providers.length;

        const finish = value => {
          if (settled) return;
          settled = true;
          clearTimeout(timer);
          if (externalSignal) externalSignal.removeEventListener('abort', onAbort);
          resolve(value);
          try {
            controller.abort();
          } catch (error) {
            /* already aborted */
          }
        };

        const onAbort = () => finish(null);
        const timer = setTimeout(() => finish(null), timeoutMs);
        if (externalSignal) {
          if (externalSignal.aborted) {
            finish(null);
            return;
          }
          externalSignal.addEventListener('abort', onAbort, { once: true });
        }

        providers.forEach(provider => {
          Promise.resolve()
            .then(() => fetchJson(provider.url, { signal: controller.signal, timeoutMs: GEO_REQUEST_TIMEOUT_MS }))
            .then(payload => {
              const parsed = provider.parse(payload);
              if (parsed) finish(parsed);
            })
            .catch(() => {
              /* a failing provider simply loses the race */
            })
            .then(() => {
              pending -= 1;
              if (pending === 0) finish(null);
            });
        });
      });
    }

    /** Build a short, human-readable place name from a reverse-geocode payload. */
    function localityLabel(payload) {
      if (!payload || typeof payload !== 'object') return '';
      const city = cleanName(payload.city);
      const locality = cleanName(payload.locality);
      const region = cleanName(payload.principalSubdivision);
      const country = cleanName(payload.countryName);
      const parts = [];
      if (city) parts.push(city);
      if (locality && locality !== city) parts.push(locality);
      if (parts.length === 0 && region) parts.push(region);
      if (parts.length === 0 && country) parts.push(country);
      return parts.join(' · ');
    }

    /**
     * Name the coordinates. Best-effort: the caller falls back to the IP provider's
     * city or to formatted coordinates when this returns nothing.
     */
    async function reverseGeocode(fetchJson, lat, lon, options) {
      const settings = options || {};
      const language = settings.language === 'en' ? 'en' : 'zh-Hans';
      const url = `${REVERSE_GEOCODE_URL}?latitude=${encodeURIComponent(lat)}&longitude=${encodeURIComponent(lon)}&localityLanguage=${language}`;
      const payload = await fetchJson(url, {
        signal: settings.signal,
        timeoutMs: settings.timeoutMs || GEO_REQUEST_TIMEOUT_MS
      });
      const label = localityLabel(payload);
      return {
        label,
        city: cleanName(payload && payload.city),
        locality: cleanName(payload && payload.locality),
        region: cleanName(payload && payload.principalSubdivision),
        country: cleanName(payload && payload.countryName),
        countryCode: cleanName(payload && payload.countryCode).toUpperCase()
      };
    }

    /** Normalize one geocoding hit into the shape the picker renders. */
    function normalizeCityHit(raw) {
      if (!raw || typeof raw !== 'object') return null;
      const lat = toFiniteNumber(raw.latitude);
      const lon = toFiniteNumber(raw.longitude);
      if (lat === null || lon === null) return null;
      const name = cleanName(raw.name);
      if (!name) return null;
      // Open-Meteo 的 admin2 对中国来说通常是地级市，而 name 才可能是区县名；
      // 之前的版本直接把 admin2 当 district，会让「选城市」被误判成「选了某个区」。
      const admin2 = cleanName(raw.admin2);
      const nameIsDistrict = looksLikeDistrict(name);
      const admin2IsDistrict = looksLikeDistrict(admin2);
      let cityName = admin2 || name;
      let district = '';
      if (nameIsDistrict && admin2 && !admin2IsDistrict) {
        cityName = admin2;
        district = name;
      } else if (admin2IsDistrict && name !== admin2) {
        cityName = name;
        district = admin2;
      }
      return {
        id: raw.id,
        name,
        region: cleanName(raw.admin1),
        subtitle: [cleanName(raw.admin1), cleanName(raw.country)].filter(Boolean).join(' · '),
        city: cityName,
        district,
        country: cleanName(raw.country),
        countryCode: cleanName(raw.country_code).toUpperCase(),
        featureCode: cleanName(raw.feature_code),
        source: 'geocoding',
        lat,
        lon
      };
    }

    /** Score a hit so cities outrank islands and exact names win. */
    function scoreCityHit(hit, query) {
      let score = 0;
      const normalized = String(query || '').trim();
      if (normalized && hit.name === normalized) score += 100;
      else if (normalized && (hit.name === `${normalized}市` || hit.name === `${normalized}县`)) score += 80;
      else if (normalized && hit.name.startsWith(normalized)) score += 20;
      switch (hit.featureCode) {
        case 'PPLC':
          score += 60;
          break;
        case 'PPLA':
          score += 50;
          break;
        case 'PPLA2':
          score += 40;
          break;
        case 'PPLA3':
        case 'PPLA4':
          score += 25;
          break;
        case 'PPL':
          score += 15;
          break;
        default:
          score -= 20;
      }
      return score;
    }

    /**
     * Search cities by name.
     *
     * Chinese city names are ambiguous in the GeoNames index (`青岛` alone can miss
     * the city), so a `市` variant is queried in parallel and the merged list is
     * ranked by exact-name matches and settlement feature codes.
     */
    async function searchCities(fetchJson, query, options) {
      const settings = options || {};
      const text = String(query || '').trim();
      if (!text) return [];
      const language = settings.language === 'en' ? 'en' : 'zh';
      const limit = Number.isFinite(settings.limit) ? settings.limit : 6;
      // 本地区县索引先出结果（不联网、无延迟），覆盖 Open-Meteo 搜不到的区县名。
      const local = searchDistricts(text, { lang: language, limit });

      const variants = [text];
      if (/[\u4e00-\u9fa5]/.test(text) && !/[市县区州盟旗]$/.test(text)) variants.push(`${text}市`);

      const batches = await Promise.all(variants.map(name => {
        const url = `${CITY_SEARCH_URL}?name=${encodeURIComponent(name)}&count=20&language=${language}&format=json`;
        return fetchJson(url, { signal: settings.signal, timeoutMs: settings.timeoutMs || GEO_REQUEST_TIMEOUT_MS })
          .then(payload => (payload && Array.isArray(payload.results) ? payload.results : []))
          .catch(() => []);
      }));

      const byId = new Map();
      batches.forEach(batch => {
        batch.forEach(raw => {
          const hit = normalizeCityHit(raw);
          if (!hit) return;
          const key = hit.id === undefined || hit.id === null ? `${hit.name}|${hit.lat}|${hit.lon}` : String(hit.id);
          if (!byId.has(key)) byId.set(key, hit);
        });
      });

      const remote = Array.from(byId.values())
        .map(hit => ({ ...hit, score: scoreCityHit(hit, text) }))
        .sort((left, right) => right.score - left.score);

      // 本地索引在前（区县精确），网络结果补位；同名同坐标只留一条。
      const merged = [];
      const seen = new Set();
      const push = hit => {
        if (!hit) return;
        const key = `${hit.name}|${Number(hit.lat).toFixed(1)}|${Number(hit.lon).toFixed(1)}`;
        if (seen.has(key)) return;
        seen.add(key);
        merged.push(hit);
      };
      local.forEach(push);
      remote.forEach(push);
      return merged.slice(0, limit);
    }

    /* ---- src/lib/weather.js ---- */
    /**
     * Open-Meteo forecast: one request, normalized once.
     *
     * The API returns column-oriented arrays with sparse nulls, which is awkward to
     * render and impossible to cache meaningfully as-is. `normalizeForecast` turns
     * one response into a compact row-oriented snapshot that the view walks once
     * and the cache can store verbatim.
     *
     * Time handling: every timestamp Open-Meteo returns is *local* to the requested
     * coordinates (`timezone=auto`, iso8601, no offset suffix), so all comparisons
     * here are plain string comparisons — no time-zone math, no DST surprises.
     */

    const FORECAST_ENDPOINT = 'https://api.open-meteo.com/v1/forecast';
    /** Today plus the five days the panel shows as "未来 5 天". */
    const FORECAST_DAYS = 6;
    const UPCOMING_HOURS = 24;

    const CURRENT_VARIABLES = [
      'temperature_2m',
      'relative_humidity_2m',
      'apparent_temperature',
      'is_day',
      'precipitation',
      'weather_code',
      'cloud_cover',
      'pressure_msl',
      'surface_pressure',
      'wind_speed_10m',
      'wind_direction_10m',
      'wind_gusts_10m'
    ];

    const HOURLY_VARIABLES = [
      'temperature_2m',
      'precipitation_probability',
      'precipitation',
      'weather_code',
      'wind_speed_10m'
    ];

    const DAILY_VARIABLES = [
      'weather_code',
      'temperature_2m_max',
      'temperature_2m_min',
      'apparent_temperature_max',
      'apparent_temperature_min',
      'sunrise',
      'sunset',
      'uv_index_max',
      'precipitation_sum',
      'precipitation_probability_max',
      'precipitation_hours',
      'wind_speed_10m_max',
      'wind_gusts_10m_max',
      'wind_direction_10m_dominant'
    ];

    function numericOrNull(value) {
      const numeric = typeof value === 'string' ? Number(value) : value;
      return typeof numeric === 'number' && Number.isFinite(numeric) ? numeric : null;
    }

    function stringOrEmpty(value) {
      return typeof value === 'string' ? value : '';
    }

    function valueAt(column, index) {
      if (!Array.isArray(column)) return null;
      return numericOrNull(column[index]);
    }

    function textAt(column, index) {
      if (!Array.isArray(column)) return '';
      return stringOrEmpty(column[index]);
    }

    /** Build the single request that feeds the whole panel. */
    function buildForecastUrl(lat, lon, options) {
      const settings = options || {};
      const params = new URLSearchParams();
      params.set('latitude', String(lat));
      params.set('longitude', String(lon));
      params.set('current', CURRENT_VARIABLES.join(','));
      params.set('hourly', HOURLY_VARIABLES.join(','));
      params.set('daily', DAILY_VARIABLES.join(','));
      params.set('timezone', 'auto');
      params.set('forecast_days', String(settings.forecastDays || FORECAST_DAYS));
      // Units stay metric on the wire; the view converts for °F/mph when asked.
      params.set('temperature_unit', 'celsius');
      params.set('wind_speed_unit', 'kmh');
      params.set('precipitation_unit', 'mm');
      return `${FORECAST_ENDPOINT}?${params.toString()}`;
    }

    function normalizeDaily(raw) {
      if (!raw || !Array.isArray(raw.time)) return [];
      return raw.time.map((date, index) => ({
        date: stringOrEmpty(date),
        weatherCode: valueAt(raw.weather_code, index),
        tempMax: valueAt(raw.temperature_2m_max, index),
        tempMin: valueAt(raw.temperature_2m_min, index),
        apparentMax: valueAt(raw.apparent_temperature_max, index),
        apparentMin: valueAt(raw.apparent_temperature_min, index),
        sunrise: textAt(raw.sunrise, index),
        sunset: textAt(raw.sunset, index),
        uvMax: valueAt(raw.uv_index_max, index),
        precipitationSum: valueAt(raw.precipitation_sum, index),
        precipitationProbabilityMax: valueAt(raw.precipitation_probability_max, index),
        precipitationHours: valueAt(raw.precipitation_hours, index),
        windMax: valueAt(raw.wind_speed_10m_max, index),
        gustMax: valueAt(raw.wind_gusts_10m_max, index),
        windDirectionDominant: valueAt(raw.wind_direction_10m_dominant, index)
      }));
    }

    function normalizeHourly(raw) {
      if (!raw || !Array.isArray(raw.time)) return [];
      return raw.time.map((time, index) => ({
        time: stringOrEmpty(time),
        temperature: valueAt(raw.temperature_2m, index),
        precipitationProbability: valueAt(raw.precipitation_probability, index),
        precipitation: valueAt(raw.precipitation, index),
        weatherCode: valueAt(raw.weather_code, index),
        windSpeed: valueAt(raw.wind_speed_10m, index)
      }));
    }

    /**
     * Normalize one forecast payload.
     * @returns {object|null} `null` when the payload is unusable (no `current` block)
     */
    function normalizeForecast(payload) {
      if (!payload || typeof payload !== 'object') return null;
      const currentRaw = payload.current;
      if (!currentRaw || typeof currentRaw !== 'object') return null;
      return {
        timezone: stringOrEmpty(payload.timezone),
        utcOffsetSeconds: numericOrNull(payload.utc_offset_seconds),
        elevation: numericOrNull(payload.elevation),
        current: {
          time: stringOrEmpty(currentRaw.time),
          temperature: numericOrNull(currentRaw.temperature_2m),
          apparentTemperature: numericOrNull(currentRaw.apparent_temperature),
          humidity: numericOrNull(currentRaw.relative_humidity_2m),
          precipitation: numericOrNull(currentRaw.precipitation),
          weatherCode: numericOrNull(currentRaw.weather_code),
          cloudCover: numericOrNull(currentRaw.cloud_cover),
          pressure: numericOrNull(currentRaw.pressure_msl),
          surfacePressure: numericOrNull(currentRaw.surface_pressure),
          windSpeed: numericOrNull(currentRaw.wind_speed_10m),
          windDirection: numericOrNull(currentRaw.wind_direction_10m),
          windGusts: numericOrNull(currentRaw.wind_gusts_10m),
          isDay: currentRaw.is_day === 1 || currentRaw.is_day === true
        },
        daily: normalizeDaily(payload.daily),
        hourly: normalizeHourly(payload.hourly)
      };
    }

    /**
     * Hours from the current hour onward.
     *
     * `current.time` is `YYYY-MM-DDTHH:mm` local to the location and `hourly.time`
     * rows share that format, so string comparison finds the first future hour.
     */
    function selectUpcomingHours(hours, currentTime, count) {
      if (!Array.isArray(hours) || hours.length === 0) return [];
      const limit = Number.isFinite(count) ? count : UPCOMING_HOURS;
      const anchor = typeof currentTime === 'string' && currentTime.length >= 13 ? `${currentTime.slice(0, 13)}:00` : '';
      let start = 0;
      if (anchor) {
        const found = hours.findIndex(hour => hour && typeof hour.time === 'string' && hour.time >= anchor);
        start = found === -1 ? 0 : found;
      }
      return hours.slice(start, start + limit);
    }

    /** The `daysAhead`-th daily entry (0 = today), or `null`. */
    function dayAhead(days, daysAhead) {
      if (!Array.isArray(days)) return null;
      return days[daysAhead] || null;
    }

    /** The next `count` days after today, which is what "未来 3 天" means. */
    function upcomingDays(days, count) {
      if (!Array.isArray(days)) return [];
      return days.slice(1, 1 + (Number.isFinite(count) ? count : 3));
    }

    /* ---- src/lib/history.js ---- */
    /**
     * 历史气温曲线（不是 K 线）：直接取 Open-Meteo 的逐日最高 / 最低 / 平均。
     *
     * 用 forecast 主机的 `past_days`（配额和 archive 分开），失败再退到
     * historical-forecast 主机与 archive 主机 —— 三台都试不到才报错。
     * `forecast_days=0` 只回过去，不含今天，意味着点都是**完整日**（截至昨天）。
     */


    const HISTORY_RANGES = [7, 30];
    const HISTORY_DEFAULT_RANGE = 7;
    /** 主站 → 备用主机 → archive（archive 需要 start/end 日期，单独构造）。 */
    const HISTORY_HOSTS = [
      'https://api.open-meteo.com/v1/forecast',
      'https://historical-forecast-api.open-meteo.com/v1/forecast'
    ];

    const HISTORY_DAILY_FIELDS = 'temperature_2m_max,temperature_2m_min,temperature_2m_mean';

    function normalizeRange(range) {
      const value = Math.round(Number(range));
      return HISTORY_RANGES.includes(value) ? value : HISTORY_DEFAULT_RANGE;
    }

    function buildHistoryUrl(host, lat, lon, days, options) {
      const range = normalizeRange(days);
      const timezone = (options && options.timezone) || 'Asia/Shanghai';
      return `${host}?latitude=${lat}&longitude=${lon}`
        + `&daily=${HISTORY_DAILY_FIELDS}`
        + `&past_days=${range}&forecast_days=0`
        + `&timezone=${encodeURIComponent(timezone)}`;
    }

    function buildArchiveUrl(lat, lon, startIso, endIso, options) {
      const timezone = (options && options.timezone) || 'Asia/Shanghai';
      return `https://archive-api.open-meteo.com/v1/archive?latitude=${lat}&longitude=${lon}`
        + `&daily=${HISTORY_DAILY_FIELDS}`
        + `&start_date=${startIso}&end_date=${endIso}`
        + `&timezone=${encodeURIComponent(timezone)}`;
    }

    function toDateIso(ms) {
      const date = new Date(ms);
      const pad = value => String(value).padStart(2, '0');
      return `${date.getUTCFullYear()}-${pad(date.getUTCMonth() + 1)}-${pad(date.getUTCDate())}`;
    }

    /** archive 的日期窗口：过去 range 天，截止到 6 天前（ERA5 有滞后）。 */
    function archiveWindow(days, nowMs) {
      const range = normalizeRange(days);
      const now = isNumber(nowMs) ? nowMs : Date.now();
      const end = now - 6 * 86400000;
      const start = end - (range - 1) * 86400000;
      return { start: toDateIso(start), end: toDateIso(end) };
    }

    /** Open-Meteo daily 返回 → [{ date, max, min, mean }]，只保留有数据的日期。 */
    function normalizeHistory(payload, days) {
      const daily = payload && payload.daily ? payload.daily : null;
      if (!daily || !Array.isArray(daily.time)) return [];
      const range = normalizeRange(days);
      const rows = [];
      for (let index = 0; index < daily.time.length; index += 1) {
        const date = daily.time[index];
        const max = isNumber(daily.temperature_2m_max ? daily.temperature_2m_max[index] : null)
          ? daily.temperature_2m_max[index] : null;
        const min = isNumber(daily.temperature_2m_min ? daily.temperature_2m_min[index] : null)
          ? daily.temperature_2m_min[index] : null;
        const mean = isNumber(daily.temperature_2m_mean ? daily.temperature_2m_mean[index] : null)
          ? daily.temperature_2m_mean[index] : null;
        if (max === null && min === null && mean === null) continue;
        rows.push({ date, max, min, mean });
      }
      return rows.slice(-range);
    }

    function historySummary(rows) {
      const list = Array.isArray(rows) ? rows : [];
      const highs = list.map(row => row.max).filter(isNumber);
      const lows = list.map(row => row.min).filter(isNumber);
      const means = list.map(row => row.mean).filter(isNumber);
      const average = values => (values.length
        ? +(values.reduce((sum, value) => sum + value, 0) / values.length).toFixed(1)
        : null);
      return {
        high: highs.length ? Math.max(...highs) : null,
        low: lows.length ? Math.min(...lows) : null,
        mean: average(means)
      };
    }

